// 토큰 발급 노드에서 access_token 가져오기
const token = $('토큰 발급').first().json.access_token;
const baseUrl = 'https://api.commerce.naver.com/external/v1/categories';
const headers = { 'Authorization': `Bearer ${token}` };

// 대분류 조회 결과 파싱
const l1Response = $input.first().json;
let l1List = [];
if (Array.isArray(l1Response)) {
  l1List = l1Response;
} else {
  l1List = l1Response.categories || l1Response.data || l1Response.list ||
    Object.values(l1Response).find(v => Array.isArray(v)) || [];
}

const allRows = [];

// 트리가 내장된 경우 재귀 평탄화
function flattenTree(categories, parentId, depth, pathParts) {
  for (const cat of (categories || [])) {
    const id = cat.id || cat.categoryId;
    const name = cat.name || cat.categoryName || cat.wholeCategoryName;
    if (!id || !name) continue;
    const currentPath = [...pathParts, name];
    allRows.push({
      category_id: String(id),
      category_name: name,
      parent_id: parentId ? String(parentId) : '',
      depth: depth,
      full_path: currentPath.join(' > ')
    });
    if (cat.children && cat.children.length > 0) {
      flattenTree(cat.children, id, depth + 1, currentPath);
    }
  }
}

// 응답에 children 포함 여부 확인
const hasEmbedded = l1List.length > 0 && ('children' in l1List[0] || 'child' in l1List[0]);

if (hasEmbedded) {
  // 트리 통째로 반환된 경우 - 평탄화만
  flattenTree(l1List, null, 1, []);
} else {
  // 레벨별 API 호출 필요
  for (const l1 of l1List) {
    const l1Id = l1.id || l1.categoryId;
    const l1Name = l1.name || l1.categoryName;
    if (!l1Id || !l1Name) continue;
    const l1Path = [l1Name];

    allRows.push({
      category_id: String(l1Id),
      category_name: l1Name,
      parent_id: '',
      depth: 1,
      full_path: l1Name
    });

    // 중분류 조회
    try {
      const l2Resp = await fetch(`${baseUrl}/${l1Id}`, { headers });
      if (l2Resp.ok) {
        const l2Data = await l2Resp.json();
        const l2List = Array.isArray(l2Data)
          ? l2Data
          : (l2Data.children || l2Data.childrenCategories || l2Data.categories || []);

        for (const l2 of l2List) {
          const l2Id = l2.id || l2.categoryId;
          const l2Name = l2.name || l2.categoryName;
          if (!l2Id || !l2Name) continue;
          const l2Path = [...l1Path, l2Name];

          allRows.push({
            category_id: String(l2Id),
            category_name: l2Name,
            parent_id: String(l1Id),
            depth: 2,
            full_path: l2Path.join(' > ')
          });

          // 소분류 조회
          try {
            const l3Resp = await fetch(`${baseUrl}/${l2Id}`, { headers });
            if (l3Resp.ok) {
              const l3Data = await l3Resp.json();
              const l3List = Array.isArray(l3Data)
                ? l3Data
                : (l3Data.children || l3Data.childrenCategories || l3Data.categories || []);

              for (const l3 of l3List) {
                const l3Id = l3.id || l3.categoryId;
                const l3Name = l3.name || l3.categoryName;
                if (!l3Id || !l3Name) continue;

                allRows.push({
                  category_id: String(l3Id),
                  category_name: l3Name,
                  parent_id: String(l2Id),
                  depth: 3,
                  full_path: [...l2Path, l3Name].join(' > ')
                });
              }
            }
          } catch (e3) {
            // 소분류 조회 실패 시 건너뜀
          }
        }
      }
    } catch (e2) {
      // 중분류 조회 실패 시 건너뜀
    }
  }
}

if (allRows.length === 0) {
  throw new Error('카테고리 데이터를 가져오지 못했습니다. API 응답 구조를 확인하세요.');
}

return allRows.map(row => ({ json: row }));
